            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "Every man is, no doubt, by nature, first and principally recommended to his own care; and as he is fitter to take care of himself than of any other person, it is fit and right that it should be so.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "mercy to the guilty is cruelty to the innocent", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "We are delighted to find a person who values us as we value ourselves, and distinguishes us from the rest of mankind, with an attention not unlike that with which we distinguish ourselves.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "It is reason, principle, conscience, the inhabitant of the breast, the man within, the great judge and arbiter of our conduct.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "When the happiness or misery of others depends in any respect upon our conduct, we dare not, as self-love might suggest to us, prefer the interest of one to that of many.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The great source of both the misery and disorders of human life, seems to arise from over-rating the difference between one permanent situation and another.", Author = "Adam Smith" },
