            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "In ease of body and peace of mind, all the different ranks of life are nearly upon a level, and the beggar, who suns himself by the side of the highway, possesses that security which kings are fighting for.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "There is not a negro from the coast of Africa who does not, in this respect, possess a degree of magnanimity which the soul of his sordid master is too often scarce capable of conceiving.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "Every man, as the Stoics used to say, is first and principally recommended to his own care; and every man is certainly, in every respect, fitter and abler to take care of himself than of any other person.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The man of system, on the contrary, is apt to be very wise in his own conceit; and is often so enamoured with the supposed beauty of his own ideal plan of government, that he cannot suffer the smallest deviation from any part of it.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The wise and virtuous man is at all times willing that his own private interests should be sacrificed to the public interest of his own particular society.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The administration of the great system of the universe, however, the care of the universal happiness of all rational and sensible beings, is the business of God and not of man.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The man who esteems himself as he ought, and no more than he ought, seldom fails to obtain from other people all the esteem that he himself thinks due.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The virtue of frugality lies in a middle between avarice and profusion, of which the one consists in an excess, the other in a defect of the proper attention to the objects of self-interest.", Author = "Adam Smith" },
