            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "We rarely hear, it has been said, of the combinations of masters, though frequently of those of the workman. But whoever imagines, upon this account, that masters rarely combine, is as ignorant of the world as of the subject.", Author = "Adam Smith" },
