            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "No society can surely be flourishing and happy, of which the greater part of the members are poor and miserable.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "It appears, accordingly, from the experience of all ages and nations, I believe, that the work done by freemen comes cheaper in the end than that performed by slaves.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The liberal reward of labour, therefore, as it is the affect of increasing wealth, so it is the cause of increasing population.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "When profit diminishes, merchants are very apt to complain that trade decays; though the diminution of profit is the natural effect of its prosperity, or of a greater stock being employed in it than before.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "Money, says the proverb, makes money. When you have a little, it is often easier to get more. The great difficulty is to get that little.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "They say nothing concerning the bad effects of high profits. They are silent with regard to the pernicious effects of their own gains. They complain only of those of other people.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The establishment of any new manufacture, of any new branch of commerce, or any new practice in agriculture, is always a speculation, from which the projector promises himself extraordinary profits.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "When the trade or practice becomes thoroughly established and well known, the competition reduces them to the level of other trades.", Author = "Adam Smith" },
