            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "They are upon that the greatest of all improvements.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "With the greater part of rich people, the chief enjoyment of riches consists in the parade of riches, which in their eye is never so complete as when they appear to possess those decisive marks of opulence which nobody can possess but themselves.", Author = "Adam Smith" },
