            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "It is the natural effect of improvement, however, to diminish gradually the real price of almost all manufactures.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The interest of the dealers, however, in any particular branch of trade or manufactures, is always in some respects different from, and even opposite to, that of the public.", Author = "Adam Smith" },
