            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The proposal of any new law or regulation of commerce which comes from this order, ought always to be listened to with great precaution, and ought never to be adopted till after having been long and carefully examined, not only with the most scrupulous, but with the most suspicious attention.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "It comes from an order of men, whose interest is never exactly the same with that of the public, who have generally an interest to deceive and even to oppress the public, and who accordingly have, upon many occasions, both deceived and oppressed it.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "His capital is continually going from him in one shape, and returning to him in another, and it is only by means of such circulation, or successive exchanges, that it can yield him any profit.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "No fixed capital can yield any revenue but by means of a circulating capital.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The labour of a menial servant, on the contrary, adds to the value of nothing.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The annual produce of the land and labour of any nation can be increased in its value by no other means, but by increasing either the number of its productive labourers, or the productive powers of those labourers who had before been employed.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "Though the profusion of Government must undoubtedly have retarded the natural progress of England to wealth and improvement, it has not been able to stop it.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "It is the highest impertinence and presumption, therefore, in kings and ministers, to pretend to watch over the economy of private people, and to restrain their expence, either by sumptuary laws, or by prohibiting the importation of foreign luxuries.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "If their own extravagance does not ruin the state, that of their subjects never will.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "It seldom happens, however, that a great proprietor is a great improver.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "Avarice and injustice are always shortsighted, and they did not foresee how much this regulation must obstruct improvement, and thereby hurt in the long-run the real interest of the landlord.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "But what all the violence of the feudal institutions could never have effected, the silent and insensible operation of foreign commerce and manufactures gradually brought about.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "All for ourselves, and nothing for other people, seems, in every age of the world, to have been the vile maxim of the masters of mankind.", Author = "Adam Smith" },
