            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "The great affair, we always find, is to get money.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "When the profits of trade happen to be greater than ordinary, over-trading becomes a general error both among great and small dealers.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "It would be too ridiculous to go about seriously to prove that wealth does not consist in money, or in gold and silver; but in what money purchases, and is valuable only for purchasing.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "Goods can serve many other purposes besides purchasing money, but money can serve no other purpose besides purchasing goods.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "It is not for its own sake that men desire money, but for the sake of what they can purchase with it.", Author = "Adam Smith" },
