            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "Every individual is continually exerting himself to find out the most advantageous employment for whatever capital he can command.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "By pursuing his own interest he frequently promotes that of the society more effectually than when he really intends to promote it.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "I have never known much good done by those who affected to trade for the public good.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "To give the monopoly of the home-market to the produce of domestic industry, in any particular art or manufacture, is in some measure to direct private people in what manner they ought to employ their capitals, and must, in almost all cases, be either a useless or a hurtful regulation.", Author = "Adam Smith" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Adam_Smith", Text = "What is prudence in the conduct of every private family, can scarce be folly in that of a great kingdom.", Author = "Adam Smith" },
